(()=>{const controls=[...document.querySelectorAll('[data-read-aloud]')];if(!controls.length||!('speechSynthesis'in window)){controls.forEach(x=>x.remove());return}let active=null;const getVoices=()=>speechSynthesis.getVoices();const populate=c=>{const lang=c.dataset.lang==='en'?'en':'tr',sel=c.querySelector('select'),voices=getVoices().filter(v=>v.lang.toLowerCase().startsWith(lang));sel.querySelectorAll('option:not(:first-child)').forEach(x=>x.remove());voices.forEach(v=>{const o=document.createElement('option');o.value=v.name;o.textContent=`${v.name} (${v.lang})`;sel.appendChild(o)});if(lang==='tr'){const preferred=voices.find(v=>/Hazel|Emel|Tolga|Turkish/i.test(v.name+' '+v.lang));if(preferred)sel.value=preferred.name}};controls.forEach(populate);speechSynthesis.onvoiceschanged=()=>controls.forEach(populate);const stop=()=>{speechSynthesis.cancel();if(active){active.querySelector('button b').textContent=active.dataset.lang==='en'?'Listen to this article':'Yazıyı dinle';active.querySelector('.read-icon').textContent='▶';active.querySelector('button').setAttribute('aria-pressed','false');active=null}};controls.forEach(c=>c.querySelector('button').onclick=()=>{if(active===c){stop();return}stop();const body=document.querySelector('.article-body,.odap-article-body');if(!body)return;const text=body.innerText.replace(/\s+/g,' ').trim();if(!text)return;const u=new SpeechSynthesisUtterance(text);u.lang=c.dataset.lang==='en'?'en-GB':'tr-TR';const selected=c.querySelector('select').value,voice=getVoices().find(v=>v.name===selected);if(voice)u.voice=voice;u.rate=.96;u.pitch=1;u.onend=stop;u.onerror=stop;speechSynthesis.speak(u);active=c;c.querySelector('button b').textContent=c.dataset.lang==='en'?'Stop':'Durdur';c.querySelector('.read-icon').textContent='■';c.querySelector('button').setAttribute('aria-pressed','true');c.querySelector('.read-status').textContent=c.dataset.lang==='en'?'Browser voice':'Tarayıcı sesi'});window.addEventListener('pagehide',stop)})();
